#include <map>
#include <functional>
#include <string>

// Defining the sorting criterion (std::greater) as part of the type
using DescMap = std::map<float, std::string, std::greater<float>>;
using AscMap = std::map<float, std::string, std::less<float>>;

int main() {
    DescMap d_coll;
    AscMap a_coll;

    // d_coll = a_coll; // ERROR: Incompatible types due to different comparators

    d_coll[5.0f] = "Five";
    d_coll[1.0f] = "One";
    // Iterating d_coll yields (5.0, 1.0) order.
}
